// Mock: cada form.show() consome a próxima resposta da fila `responses`.
export const responses = [];
export const shown = [];
class Base {
  constructor() { this.buttons = []; this._title = ""; this.controls = []; }
  title(t) { this._title = t; return this; }
  body() { return this; }
  button(t) { this.buttons.push(t); return this; }
  toggle(l, o) { this.controls.push(["toggle", l, o]); return this; }
  slider(l, a, b, o) { this.controls.push(["slider", l, a, b, o]); return this; }
  dropdown(l, opts, o) { this.controls.push(["dropdown", l, opts, o]); return this; }
  submitButton() { return this; }
  async show() {
    shown.push(this);
    const r = responses.shift();
    if (typeof r === "function") return r(this);
    return r ?? { canceled: true };
  }
}
export class ActionFormData extends Base {}
export class ModalFormData extends Base {}
